import { un_or_register_members_for_event } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    rowInfo: Object,
    displayEvents: Boolean
  },
  data() {
    return {
      loading: false,
      event_date: "",
      user_email_id: "",
      user_name: ""
    };
  },
  watch: {
    displayEvents: {
      async handler() {
        if (this.displayEvents == true) {
          this.event_date = this.fetch_value(this.rowInfo.info.from_date) + " - " + this.fetch_value(this.rowInfo.info.to_date);
          this.user_email_id = this.$store.getters.GetUserObj.user.user_email_id;
          this.user_name = this.$store.getters.GetUserObj.user.full_user_name;
          // console.log(this.rowInfo.info);
        }
      },
      immediate: true
    }
  },
  methods: {
    fetch_value(date) {
      const dates = new Date(date);
      const a = dates.toLocaleDateString();
      return a.toUpperCase();
    },
    validate() {
      if (this.rowInfo.info.register_users.includes(this.rowInfo.info.register_users)) {
        this.$emit("check", 0);
      } else if (this.rowInfo.info.available_capcity == "0") {
        this.$emit("check", 1);
      } else {
        this.register_event();
      }
    },
    close_dialog() {
      this.$emit("clciked", 0);
    },
    async unregister_event() {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(un_or_register_members_for_event, {
          input: {
            register_status: "UNREGISTER",
            event_id: this.rowInfo.info.event_id,
            user_id: data.user.user_id,
            user_email_id: this.user_email_id
          }
        }));
        var response = JSON.parse(result.data.un_or_register_members_for_event);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.$emit("errorMsg", error.errors[0].message);
        this.loading = false;
      }
    },
    async register_event() {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(un_or_register_members_for_event, {
          input: {
            register_status: "REGISTER",
            event_id: this.rowInfo.info.event_id,
            user_id: data.user.user_id,
            user_email_id: this.user_email_id
          }
        }));
        var response = JSON.parse(result.data.un_or_register_members_for_event);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.$emit("errorMsg", error.errors[0].message);
        this.loading = false;
      }
    }
  }
};
